"use client";

import { useEffect, useRef } from "react";
import { BookOpen, FileSearch, ListChecks, Search, Sparkles, TriangleAlert, Wrench } from "lucide-react";
import type { TraceEntry, TraceStats } from "@/lib/client/history";

/**
 * Live research feed. Every line is an observable provider event (plan,
 * search query, result, tool call, status) with its own timestamp. Nothing
 * here is generated by the UI; when the provider is quiet the feed is quiet.
 */

const ICON: Record<TraceEntry["type"], React.ComponentType<{ className?: string }>> = {
  plan: ListChecks,
  search: Search,
  result: FileSearch,
  tool_call: Wrench,
  exec_status: Sparkles,
  extract: BookOpen,
  status: Sparkles,
  error: TriangleAlert,
};

const LABEL: Record<TraceEntry["type"], string> = {
  plan: "Plan",
  search: "Search",
  result: "Found",
  tool_call: "Tool",
  exec_status: "Status",
  extract: "Reading",
  status: "Status",
  error: "Error",
};

function splitSearch(message: string): { label: string; text: string } {
  const m = message.match(/^(Objective|Query)\s*:\s*(.*)$/i);
  if (!m) return { label: "Search", text: message };
  return { label: m[1].toLowerCase() === "query" ? "Searching" : "Objective", text: m[2] };
}

/** "Extract: https://…" becomes a readable "Reading host/path" line with a link. */
function splitExtract(message: string): { label: string; text: string; url?: string } {
  const m = message.match(/^Extract\s*:\s*(https?:\/\/\S+)$/i);
  if (!m) return { label: "Reading", text: message };
  const url = m[1];
  try {
    const u = new URL(url);
    const path = u.pathname.length > 48 ? `…${u.pathname.slice(-44)}` : u.pathname;
    return { label: "Reading", text: `${u.hostname.replace(/^www\./, "")}${path === "/" ? "" : path}`, url };
  } catch {
    return { label: "Reading", text: url, url };
  }
}

function host(url: string): string {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return url;
  }
}

export function LiveTrace({ trace, stats, live, streamState }: { trace: TraceEntry[]; stats: TraceStats | null; live: boolean; streamState: "idle" | "open" | "reconnecting" | "closed" }) {
  const endRef = useRef<HTMLDivElement>(null);
  const listRef = useRef<HTMLOListElement>(null);
  useEffect(() => {
    if (!live) return;
    const el = listRef.current;
    if (!el) return;
    const nearBottom = el.scrollHeight - el.scrollTop - el.clientHeight < 120;
    if (nearBottom) endRef.current?.scrollIntoView({ block: "nearest", behavior: "smooth" });
  }, [trace.length, live]);

  return (
    <div>
      {stats && (
        <div className="mb-4">
          <div className="flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1 text-[13.5px] text-ink-2">
            <span>
              <span className="font-semibold text-ink">{stats.read.toLocaleString()}</span> sources read of{" "}
              <span className="font-semibold text-ink">{stats.considered.toLocaleString()}</span> considered
            </span>
            {stats.progress !== null && <span className="text-muted">Provider progress {Math.round(stats.progress)}%</span>}
          </div>
          {stats.progress !== null && (
            <div className="mt-2 h-1.5 w-full overflow-hidden rounded-full bg-rule" role="progressbar" aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.round(stats.progress)} aria-label="Provider-reported research progress">
              <div className="h-full rounded-full bg-teal transition-[width] duration-700" style={{ width: `${stats.progress}%` }} />
            </div>
          )}
          {stats.sample.length > 0 && (
            <ul className="mt-2 flex flex-wrap gap-1.5" aria-label="Sample of sources read">
              {stats.sample.slice(0, 8).map((u) => (
                <li key={u}>
                  <a href={u} target="_blank" rel="noopener noreferrer" className="inline-block max-w-[16rem] truncate rounded-[6px] border border-rule bg-paper px-2 py-0.5 text-[12px] text-ink-2 hover:border-teal hover:text-teal-deep" title={u}>
                    {host(u)}
                  </a>
                </li>
              ))}
            </ul>
          )}
        </div>
      )}

      {trace.length === 0 ? (
        <p className="text-[14px] text-muted">
          {live
            ? streamState === "reconnecting"
              ? "Reconnecting to the research stream…"
              : "Waiting for the first update from the research agent. Quick runs often report after 20–60 seconds."
            : "No live trace was recorded for this run."}
        </p>
      ) : (
        <ol ref={listRef} className={`space-y-0 ${live ? "max-h-[420px] overflow-y-auto pr-1" : ""}`} aria-live={live ? "polite" : undefined} aria-relevant="additions">
          {trace.map((t, i) => {
            const Icon = ICON[t.type];
            const isLast = i === trace.length - 1;
            const s: { label: string; text: string; url?: string } = t.type === "search" ? splitSearch(t.message) : t.type === "extract" ? splitExtract(t.message) : { label: LABEL[t.type], text: t.message };
            const quiet = t.type === "exec_status" || t.type === "status";
            return (
              <li key={`${t.at}-${i}`} className={`grid grid-cols-[1.25rem_1fr] gap-x-3 border-l border-rule py-2 pl-3 ${isLast && live ? "border-l-teal" : ""}`}>
                <Icon className={`mt-0.5 h-4 w-4 ${t.type === "error" ? "text-down" : isLast && live ? "text-teal pulse" : "text-muted"}`} aria-hidden="true" />
                <div className="min-w-0">
                  <p className={`text-[14.5px] leading-[1.5] ${quiet ? "text-muted" : "text-ink"} ${t.type === "plan" ? "font-serif text-[16px]" : ""}`}>
                    <span className="meta mr-2 align-middle">{s.label}</span>
                    {s.url ? (
                      <a href={s.url} target="_blank" rel="noopener noreferrer" className="break-all text-ink hover:text-teal-deep hover:underline">
                        {s.text}
                      </a>
                    ) : (
                      s.text
                    )}
                  </p>
                  <time dateTime={t.at} className="text-[11.5px] text-muted tabular-nums">
                    {new Date(t.at).toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit", second: "2-digit" })}
                  </time>
                </div>
              </li>
            );
          })}
          <div ref={endRef} />
        </ol>
      )}
    </div>
  );
}
